<?php
namespace Modules\ComplianceIQ\Jobs;
use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Modules\ComplianceIQ\Entities\ComplianceReport;use Modules\ComplianceIQ\Entities\ComplianceAnnotation;use Modules\ComplianceIQ\Services\Compliance\ComplianceFindingService;use Modules\TitanZeroAssurance\Services\ExecutionContextStore;use Modules\TitanZeroAssurance\ValueObjects\CompanyExecutionContext;
class AnalyzeComplianceAnomalies implements ShouldQueue {use Dispatchable,Queueable;public function __construct(public int $companyId,public int $reportId){}public function handle(ComplianceFindingService $findings,ExecutionContextStore $contexts):void {$contexts->runWith(new CompanyExecutionContext($this->companyId,'system','compliance-anomaly'),function()use($findings){$r=ComplianceReport::query()->where('company_id',$this->companyId)->find($this->reportId);if(!$r)return;$summary=(array)$r->summary;if(($summary['integrity']['valid']??true)===false){$f=$findings->finding($this->companyId,'critical','Audit integrity mismatch','compliance_report',$r->id,[],['integrity'=>$summary['integrity']]);$w=$findings->correctiveWork($f);ComplianceAnnotation::create(['company_id'=>$this->companyId,'report_id'=>$r->id,'user_id'=>null,'kind'=>'finding','severity'=>'critical','note'=>'Audit integrity mismatch requires governed investigation.','finding_json'=>['finding'=>$f->toArray(),'work_item'=>$w->toArray()]]);}});}}
